1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioResult = {
6	  results: QuoteResult[];
7	};
8	
9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const satisfies Record<string, number>;
17	
18	type InsurableItemType = keyof typeof BASE_PREMIUMS;
19	
20	type Item = {
21	  type: InsurableItemType;
22	  material?: string;
23	  enchantment?: number;
24	  cursed?: boolean;
25	};
26	
27	type QuoteStep = {
28	  op: "quote";
29	  items: Item[];
30	};
31	
32	type Customer = {
33	  yearsWithMHPCO: number;
34	};
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: QuoteStep[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
43	const CURSE_SURCHARGE_PERCENT = 50;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT_PERCENT = 20;
48	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
49	
50	const percentOf = (amount: number, percent: number): number =>
51	  (amount * percent) / 100;
52	
53	// The MHPCO always rounds in its own favour: premiums (which the customer
54	// pays) go up. Payouts round down, but no test demands that yet.
55	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
56	
57	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
58	
59	// Exactly this many components of the same type form a "building block",
60	// priced as a unit rather than per item.
61	const BUILDING_BLOCK_SIZE = 3;
62	const BUILDING_BLOCK_BASE_PREMIUM = 60;
63	
64	const sumOf = (amounts: number[]): number =>
65	  amounts.reduce((total, amount) => total + amount, 0);
66	
67	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
68	
69	const alikeItemGroups = (items: Item[]): Item[][] =>
70	  insurableItemTypes
71	    .map((type) => items.filter((item) => item.type === type))
72	    .filter((alikeItems) => alikeItems.length > 0);
73	
74	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
75	  alikeItems.length === BUILDING_BLOCK_SIZE;
76	
77	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
78	  formsBuildingBlock(alikeItems)
79	    ? BUILDING_BLOCK_BASE_PREMIUM
80	    : sumOf(alikeItems.map(itemBasePremiumOf));
81	
82	const policyBasePremiumOf = (items: Item[]): number =>
83	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
84	
85	const isCursed = (item: Item): boolean => item.cursed === true;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	// Each surcharge is a percentage of the base premium of the item that
91	// triggers it. Surcharges are cumulative: every applicable one is added.
92	type ItemSurcharge = {
93	  appliesTo: (item: Item) => boolean;
94	  percent: number;
95	};
96	
97	const ITEM_SURCHARGES: ItemSurcharge[] = [
98	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
99	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
100	];
101	
102	// Item-specific modifiers apply to the base premium of the affected item.
103	const itemModifiersOf = (item: Item): number =>
104	  sumOf(
105	    ITEM_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).map(
106	      (surcharge) => percentOf(itemBasePremiumOf(item), surcharge.percent),
107	    ),
108	  );
109	
110	const isLongStanding = (customer: Customer): boolean =>
111	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
112	
113	// A contract is one quote within a scenario; contractIndex is zero-based, so
114	// every contract after the first is a follow-up.
115	type Contract = {
116	  customer: Customer;
117	  contractIndex: number;
118	};
119	
120	const isFollowUpContract = (contract: Contract): boolean =>
121	  contract.contractIndex > 0;
122	
123	// Each policy-wide modifier is a percentage of the policy base premium.
124	// A surcharge has a positive percent, a discount a negative one, so they all
125	// combine by summing. Modifiers are cumulative: every applicable one applies.
126	type PolicyModifier = {
127	  appliesTo: (contract: Contract) => boolean;
128	  percent: number;
129	};
130	
131	const alwaysApplies = (): boolean => true;
132	
133	const POLICY_MODIFIERS: PolicyModifier[] = [
134	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
135	  {
136	    appliesTo: (contract) => isLongStanding(contract.customer),
137	    percent: -LOYALTY_DISCOUNT_PERCENT,
138	  },
139	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
140	];
141	
142	const policyModifiersOf = (
143	  policyBasePremium: number,
144	  contract: Contract,
145	): number =>
146	  sumOf(
147	    POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(contract)).map(
148	      (modifier) => percentOf(policyBasePremium, modifier.percent),
149	    ),
150	  );
151	
152	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
153	  const policyBasePremium = policyBasePremiumOf(step.items);
154	  const itemModifiers = sumOf(step.items.map(itemModifiersOf));
155	  const policyModifiers = policyModifiersOf(policyBasePremium, contract);
156	
157	  return {
158	    premium: roundedUpInMHPCOsFavour(
159	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
160	    ),
161	  };
162	};
163	
164	export const runScenario = (scenario: Scenario): ScenarioResult => {
165	  return {
166	    results: scenario.steps.map((step, contractIndex) =>
167	      quote(step, { customer: scenario.customer, contractIndex }),
168	    ),
169	  };
170	};
